Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
#include <iomanip>
#include <limits>

int main() {
    long double x, y;
    int n;
    std::cin >> x >> y >> n;

    long double target = x / y;
    long long p = 0, s = 1;
    long double minError = std::numeric_limits<long double>::max();

    for (int i = 1; i <= n; ++i) {
        long double val = target * i;
        long long candidates[2] = {static_cast<long long>(std::floor(val)),
                                   static_cast<long long>(std::ceil(val))};

        for (int j = 0; j < 2; ++j) {
            long long candidate = candidates[j];
            long double error = std::fabsl(target - static_cast<long double>(candidate) / i);
            if (error < minError) {
                minError = error;
                p = candidate;
                s = i;
            }
        }
    }

    std::cout << p << '/' << s << std::endl;
    return 0;
}
